class Solution:
    def reverseKGroup(self, head, k):
        values = []
        cur = head
        while cur:
            values.append(cur.val)
            cur = cur.next

        for start in range(0, len(values) - len(values) % k, k):
            values[start:start + k] = reversed(values[start:start + k])

        cur = head
        for value in values:
            cur.val = value
            cur = cur.next
        return head

