class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def reverseKGroup(self, head, k):
        dummy = ListNode(0)
        tail = dummy
        cur = head
        while cur:
            stack = []
            node = cur
            for _ in range(k):
                if not node:
                    tail.next = cur
                    return dummy.next
                stack.append(node)
                node = node.next
            while stack:
                tail.next = stack.pop()
                tail = tail.next
            cur = node
        tail.next = None
        return dummy.next

